64	struct WrapResult {
65	    filter: FilterResult,
66	    dedup_hit: bool,
67	    dedup_summary: Option<String>,
68	}
69	
70	fn compress(
71	    raw_output: &str,
72	    program: &str,
73	    args: &[String],
74	    session_id: &str,
75	    project_dir: &str,
76	) -> Result<WrapResult> {
77	    let data_dir = paths::data_dir();
78	    std::fs::create_dir_all(&data_dir)?;
79	    let db_path = paths::db_path();
80	
81	    let filters_dir = paths::filters_dir();
82	    let pipeline = FilterPipeline::load_from_dir(&filters_dir).unwrap_or_else(|_| FilterPipeline::new());
83	
84	    let filter_result = pipeline.apply(program, &args.iter().map(|s| s.to_string()).collect::<Vec<_>>(), raw_output);
85	
86	    let dedup_cache = DedupCache::open(&db_path, session_id)?;
87	    let content_to_check = &filter_result.output;
88	    let fake_mtime = file_content_mtime(content_to_check);
89	    let dedup_result = dedup_cache.lookup(
90	        &format!("cmd:{}:{}", program, args.join(" ")),
91	        fake_mtime,
92	        content_to_check,
93	    )?;
94	
95	    let tokens_saved_compress = if filter_result.filter_applied {
96	        estimate_tokens(filter_result.input_len) - estimate_tokens(filter_result.output_len)
97	    } else {
98	        0
99	    };
100	
101	    let tracking = TrackingDb::open(&db_path)?;
102	
103	    if filter_result.filter_applied && tokens_saved_compress > 0 {
104	        tracking.record(&TrackingEvent {
105	            command: program.to_string(),
106	            input_tokens: estimate_tokens(filter_result.input_len) as u64,
107	            output_tokens: estimate_tokens(filter_result.output_len) as u64,
108	            tokens_saved: tokens_saved_compress as u64,
109	            layer: SavingsLayer::Compression,
110	            project: project_dir.to_string(),
111	            session_id: session_id.to_string(),
112	        })?;
113	    }
114	
115	    if dedup_result.cache_hit {
116	        tracking.record(&TrackingEvent {
117	            command: program.to_string(),
118	            input_tokens: estimate_tokens(filter_result.output_len) as u64,
119	            output_tokens: 0,
120	            tokens_saved: dedup_result.tokens_saved,
121	            layer: SavingsLayer::Dedup,
122	            project: project_dir.to_string(),
123	            session_id: session_id.to_string(),
124	        })?;
125	    }
126	
127	    if let Ok(event_buf) = EventBuffer::open(&db_path) {
128	        let event = proto::Event {
129	            id: uuid::Uuid::new_v4().to_string(),
130	            timestamp_ms: chrono::Utc::now().timestamp_millis(),
131	            session_id: session_id.to_string(),
132	            project_dir: project_dir.to_string(),
133	            command: format!("{} {}", program, args.join(" ")),
134	            event_type: if dedup_result.cache_hit {
135	                proto::EventType::Dedup as i32
136	            } else {
137	                proto::EventType::Compression as i32
138	            },
139	            compression: Some(proto::CompressionEvent {
140	                input_bytes: filter_result.input_len as u64,
141	                output_bytes: filter_result.output_len as u64,
142	                input_tokens: estimate_tokens(filter_result.input_len) as u64,
143	                output_tokens: estimate_tokens(filter_result.output_len) as u64,
144	                tokens_saved: tokens_saved_compress as u64,
145	                filter_name: program.to_string(),
146	                compression_level: "default".to_string(),
147	                latency_ms: 0.0,
148	            }),
149	            dedup: if dedup_result.cache_hit {
150	                Some(proto::DedupEvent {
151	                    content_hash: dedup_result.content_hash.clone(),
152	                    cache_hit: true,
153	                    tokens_saved: dedup_result.tokens_saved,
154	                    file_path: String::new(),
155	                    latency_ms: 0.0,
156	                })
157	            } else {
158	                None
159	            },
160	        };
161	        let _ = event_buf.append(&event);
162	    }
163	
164	    Ok(WrapResult {
165	        filter: filter_result,
166	        dedup_hit: dedup_result.cache_hit,
167	        dedup_summary: dedup_result.summary,
168	    })
169	}
