171	struct CommandOutput {
172	    combined: String,
173	    exit_code: Option<i32>,
174	}
175	
176	fn run_command(program: &str, args: &[String]) -> Result<CommandOutput> {
177	    let output = Command::new(program)
178	        .args(args)
179	        .output()
180	        .map_err(|e| anyhow::anyhow!("failed to execute {}: {}", program, e))?;
181	
182	    let mut combined = String::new();
183	    if !output.stdout.is_empty() {
184	        combined.push_str(&String::from_utf8_lossy(&output.stdout));
185	    }
186	    if !output.stderr.is_empty() {
187	        if !combined.is_empty() {
